#define     MAX_SIZE        (KEY_LEN_2048<<2)
#define     HALF_MAX        (MAX_SIZE+1)>>1
typedef struct{
    uint32_t u32CompType;
    char *      pu8Name;
}RSA_COMPLETE_TPYE;
static void RsaComplete_Test()
{
    RSA_COMPLETE_TPYE ModeType[3] = {{MH_RSA_COMPLETE_E, "COMPLETE_E"},
                                     {MH_RSA_COMPLETE_D, "COMPLETE_D"},
                                     {MH_RSA_COMPLETE_CRT, "COMPLETE_CRT"}};
    uint8_t i = 0;                             
    uint8_t au8N[MAX_SIZE];
    uint8_t au8D[MAX_SIZE];
    uint8_t au8E[MAX_SIZE];
    uint8_t au8P[HALF_MAX];
    uint8_t au8Q[HALF_MAX];
    uint8_t au8Dp[HALF_MAX];
    uint8_t au8Dq[HALF_MAX];
    uint8_t au8Qi[HALF_MAX];
    uint32_t u32Ret = 0;
//    uint16_t u16NByte;
    MH_RSA_KEY_SPACE InBase;
    uint8_t u8Base = 0;
    MH_RSA_KEY KeySrc;
    for(i = 0; i < 3; i++)
    {
        u8Base = 0;
        memset(&KeySrc,0,sizeof(MH_RSA_KEY));
        memset(&InBase,0,sizeof(MH_RSA_KEY_SPACE));
        bn_read_string_from_head((uint8_t *)au8P, sizeof(au8P), RSA_P_1984);
        bn_read_string_from_head((uint8_t *)au8Q, sizeof(au8Q), RSA_Q_1984);
        if(ModeType[i].u32CompType == MH_RSA_COMPLETE_D)
        {
            bn_read_string_from_head((uint8_t *)au8D, sizeof(au8D), RSA_D_1984);
        }
        else if(ModeType[i].u32CompType == MH_RSA_COMPLETE_E)
        {
            bn_read_string_from_head((uint8_t *)au8E, sizeof(au8E), RSA_E_1984);
            KeySrc.u16EBits = 32;
        }
        else if(ModeType[i].u32CompType == MH_RSA_COMPLETE_CRT)
        {
            bn_read_string_from_head((uint8_t *)au8Dp, sizeof(au8Dp), RSA_DP_1984);
            bn_read_string_from_head((uint8_t *)au8Dq, sizeof(au8Dq), RSA_DQ_1984);
        }
        KeySrc.u16NBits = 1984;
        KeySrc.pu8P = au8P;
        KeySrc.pu8Q = au8Q;
        KeySrc.pu8E = au8E;
        KeySrc.pu8N = au8N;
        KeySrc.pu8D = au8D;
        KeySrc.pu8Dp = au8Dp;
        KeySrc.pu8Dq = au8Dq;
        KeySrc.pu8Qi = au8Qi;
        KeySrc.u32Crc = MHCRC_CalcBuff(0xffff, &KeySrc, sizeof(MH_RSA_KEY)-4); 
        u32Ret = MHRSA_CompleteKey(&KeySrc,&InBase,&u8Base,ModeType[i].u32CompType);
//        u16NByte = (KeySrc.u16NBits + 7)>>3;
        printf("\n %s RSA Complete Test Ret = %08X\n", ModeType[i].pu8Name, u32Ret);
        if(MH_RET_RSA_SUCCESS != u32Ret)
        {
            printf("RSA Private Crt Func Test Error!\n");
            while(1);
        }
//        ouputRes("N.\n", au8N, u16NByte);
//        ouputRes("D.\n", au8D, u16NByte);
//        ouputRes("E.\n", au8E, (KeySrc.u16EBits + 7)>>3);
//        ouputRes("P.\n", au8P, (u16NByte + 1)>>1);
//        ouputRes("Q.\n", au8Q, (u16NByte + 1)>>1);
//        ouputRes("Dp.\n", au8Dp, (u16NByte + 1)>>1);
//        ouputRes("Dq.\n", au8Dq, (u16NByte + 1)>>1);
//        ouputRes("Qi.\n", au8Qi, (u16NByte + 1)>>1);
        
    }
}

static void RsaGenKey_Test(void)
{
    uint32_t u32Ret = 0;
    uint32_t au32E[MAX_SIZE];
    MH_RSA_KEY_SPACE InBase;
    uint8_t u8Base = 0;
    MH_RSA_KEY KeySrc;
    
//    printf("RSA Gen start!\n");
    
    // gen key
    memset((uint8_t *)&KeySrc,0,sizeof(KeySrc));
    memset((uint8_t *)&InBase,0,sizeof(InBase));
    u8Base = 0;
    
    bn_read_string_from_head((uint8_t *)au32E, sizeof(au32E), RSA_E_2048);
    
    //  pri key para init
    KeySrc.u16NBits = 2048;
    KeySrc.u16EBits = 32;
    KeySrc.pu8E = (uint8_t *)au32E; 
    KeySrc.u32Crc = MHCRC_CalcBuff(0xffff, &KeySrc, sizeof(MH_RSA_KEY)-4); 
    u32Ret = MHRSA_GenKey(&KeySrc, &InBase, &u8Base, MH_RSA_COMPLETE_E);
    if(MH_RET_RSA_SUCCESS != u32Ret)
    {
        printf("MHRSA_GenKey Test Error! Ret = %08X\n", u32Ret);
        while(1);
    }
}

//without N E D
static void RsaCrtFunc_Test(void)
{
    uint8_t au8P[HALF_MAX];
    uint8_t au8Q[HALF_MAX];
    uint8_t au8Dp[HALF_MAX];
    uint8_t au8Dq[HALF_MAX];
    uint8_t au8Qi[HALF_MAX];
    uint8_t au8N[MAX_SIZE];
    uint8_t au8E[32];
    uint8_t au8Plain[MAX_SIZE];
    uint8_t au8Input[MAX_SIZE];
    uint8_t au8Output[MAX_SIZE];  
    uint16_t u16OutByte;
    MH_RSA_KEY_SPACE InBase;
    uint8_t u8Base = 0;
    MH_RSA_KEY KeySrc;
    MH_RSA_CALL pCall;
    bn_read_string_from_head((uint8_t *)au8P, sizeof(au8P), RSA_P_2048);
    bn_read_string_from_head((uint8_t *)au8Q, sizeof(au8Q), RSA_Q_2048);
    bn_read_string_from_head((uint8_t *)au8Dp, sizeof(au8Dp), RSA_DP_2048);
    bn_read_string_from_head((uint8_t *)au8Dq, sizeof(au8Dq), RSA_DQ_2048);
    bn_read_string_from_head((uint8_t *)au8Qi, sizeof(au8Qi), RSA_QI_2048);
    u16OutByte = bn_read_string_from_head((uint8_t *)au8Plain, sizeof(au8Plain), PLAIN_2048);   
    pCall.u32InLen = bn_read_string_from_head((uint8_t *)au8Input, sizeof(au8Input), CIPHER_2048);   
    MHRSA_Init(&KeySrc, &InBase);
     //  pri key para init
    KeySrc.u16NBits = 2048;
    KeySrc.u16EBits = 32;
    KeySrc.pu8N = au8N;
    KeySrc.pu8E = au8E;
    KeySrc.pu8P = (uint8_t *)au8P;
    KeySrc.pu8Q = (uint8_t *)au8Q;
    KeySrc.pu8Dp = (uint8_t *)au8Dp;
    KeySrc.pu8Dq = (uint8_t *)au8Dq;
    KeySrc.pu8Qi = (uint8_t *)au8Qi;
    KeySrc.u32Crc = MHCRC_CalcBuff(0xffff, &KeySrc, sizeof(MH_RSA_KEY)-4);
    MHRSA_CompleteKey(&KeySrc, &InBase, NULL, MH_RSA_COMPLETE_CRT);
    //set crt key
    MHRSA_SetKey(&KeySrc, &InBase, &u8Base);
    //set pCall 
    pCall.pu8Input = au8Input;
    pCall.pu8Output = au8Output;
    pCall.u32OutLen = u16OutByte;
    pCall.KeyBase = &InBase;
    pCall.u32Crc = MHCRC_CalcBuff(0xffff, &pCall, sizeof(MH_RSA_CALL)-4);
    if(MH_RET_RSA_SUCCESS != MHRSA_Crt(&pCall))
    {
       printf("RSA Private Crt Func Test Error!\n");
    }
    r_printf((0 == memcmp(au8Output, au8Plain,  u16OutByte)), "mh_rsa_crt test\n");
    
    
    // Efc interface Test
    pCall.pu8Input = au8Input;
    pCall.pu8Output = au8Output;
    pCall.u32OutLen = u16OutByte;
    pCall.KeyBase = &InBase;
    pCall.u32Crc = MHCRC_CalcBuff(0xffff, &pCall, sizeof(MH_RSA_CALL)-4);
    if(MH_RET_RSA_SUCCESS != MHRSA_Crt(&pCall))
    {
       printf("RSA Private Crt Func Test Error!\n");
    }
    r_printf((0 == memcmp(au8Output, au8Plain,  u16OutByte)), "mh_rsa_crt_EFC test\n");
}

static void RsaPriFunc_Test(void)
{
    uint8_t au8N[MAX_SIZE];
    uint8_t au8D[MAX_SIZE];
    uint8_t au8E[MAX_SIZE];

    uint8_t au8Plain[MAX_SIZE];
    uint8_t au8Input[MAX_SIZE];
    uint8_t au8Output[MAX_SIZE];
    MH_RSA_KEY_SPACE InBase;
    uint16_t u16OutByte;
    uint8_t u8Base = 0;
    MH_RSA_KEY KeySrc;
    MH_RSA_CALL Call;

    bn_read_string_from_head(au8N, sizeof(au8N), RSA_N_2048);
    bn_read_string_from_head(au8D, sizeof(au8D), RSA_D_2048);
    bn_read_string_from_head((uint8_t *)au8E, sizeof(au8E), RSA_E_2048);

    u16OutByte = bn_read_string_from_head(au8Plain, sizeof(au8Plain), PLAIN_2048);   
    Call.u32InLen = bn_read_string_from_head(au8Input, sizeof(au8Input), CIPHER_2048); 

    memset(&KeySrc,0,sizeof(KeySrc));
    memset(&InBase,0,sizeof(InBase));
    //  pri key para init
    KeySrc.u16NBits = 2048;
    KeySrc.u16EBits = 32;
    KeySrc.pu8N = au8N;
    KeySrc.pu8E = au8E;
    KeySrc.pu8D = au8D;

    //set pri key
    KeySrc.u32Crc = MHCRC_CalcBuff(0xffff, &KeySrc, sizeof(MH_RSA_KEY)-4);
    MHRSA_SetKey(&KeySrc, &InBase, &u8Base);    
    //set pCall
    Call.pu8Input = au8Input;
    Call.pu8Output = (uint8_t *)au8Output;
    Call.u32OutLen = u16OutByte;
    Call.KeyBase = &InBase;
    Call.u32Crc = MHCRC_CalcBuff(0xffff, &Call, sizeof(MH_RSA_CALL)-4);
    if(MH_RET_RSA_SUCCESS != MHRSA_Pri(&Call))
    {
       printf("RSA Private Func Test Error!\n");
    }
    r_printf((0 == memcmp(au8Output, au8Plain,  u16OutByte)), "mh_rsa_private test\n");
    
    //Efc interface Test
    //set pCall
    Call.pu8Input = au8Input;
    Call.pu8Output = (uint8_t *)au8Output;
    Call.u32OutLen = u16OutByte;
    Call.KeyBase = &InBase;
    Call.u32Crc = MHCRC_CalcBuff(0xffff, &Call, sizeof(MH_RSA_CALL)-4);
    if(MH_RET_RSA_SUCCESS != MHRSA_PriEfc(&Call))
    {
       printf("RSA Private Func Test Error!\n");
    }
    r_printf((0 == memcmp(au8Output, au8Plain,  u16OutByte)), "mh_rsa_private_EFC test\n");
}

static void RsaPubFunc_Test(void)
{
    uint32_t u32Ret = 0;
    uint8_t au8N[MAX_SIZE];
    uint8_t au8E[8];
    uint8_t au8Plain[MAX_SIZE];
    uint8_t au8Input[MAX_SIZE];
    uint8_t au8Output[MAX_SIZE];
    uint16_t u16OutByte;
    MH_RSA_KEY_SPACE InBase;
    MH_RSA_KEY KeySrc;
    MH_RSA_CALL Call;     
    bn_read_string_from_head(au8N, sizeof(au8N), RSA_N_2048);
    bn_read_string_from_head((uint8_t *)au8E, sizeof(au8E), RSA_E_2048);
    u16OutByte = bn_read_string_from_head((uint8_t *)au8Plain, sizeof(au8Plain), CIPHER_2048);   
    Call.u32InLen = bn_read_string_from_head((uint8_t *)au8Input, sizeof(au8Input), PLAIN_2048);  
    memset((uint8_t *)&KeySrc,0,sizeof(KeySrc));
    memset((uint8_t *)&InBase,0,sizeof(InBase));
    //  pri key para init
    KeySrc.u16NBits = 2048;
    KeySrc.u16EBits = 32;
    KeySrc.pu8N = (uint8_t *)au8N;
    KeySrc.pu8E = (uint8_t *)au8E;
    //  set pub key
    KeySrc.u32Crc = MHCRC_CalcBuff(0xffff, &KeySrc, sizeof(MH_RSA_KEY)-4);
    u32Ret = MHRSA_SetKey(&KeySrc, &InBase, NULL);   
    printf("RSA Public Func MHRSA_SetKey Ret= %08X\n", u32Ret);
    //set Call 
    Call.pu8Input = (uint8_t *)au8Input;
    Call.pu8Output = (uint8_t *)au8Output;
    Call.u32OutLen = u16OutByte;
    Call.KeyBase = &InBase;
    Call.u32Crc = MHCRC_CalcBuff(0xffff, &Call, sizeof(MH_RSA_CALL)-4);
    u32Ret = MHRSA_Pub(&Call);
    if(MH_RET_RSA_SUCCESS != u32Ret)
    {
       printf("RSA Public Func Test Error = %08X!\n", u32Ret);
    }
    r_printf((0 == memcmp(au8Output, au8Plain,  u16OutByte)), "mh_rsa_public test\n");
    
    //Efc interface Test 
    Call.pu8Input = (uint8_t *)au8Input;
    Call.pu8Output = (uint8_t *)au8Output;
    Call.u32OutLen = u16OutByte;
    Call.KeyBase = &InBase;
    Call.u32Crc = MHCRC_CalcBuff(0xffff, &Call, sizeof(MH_RSA_CALL)-4);
    u32Ret = MHRSA_PubEfc(&Call);
    if(MH_RET_RSA_SUCCESS != u32Ret)
    {
       printf("RSA Public Func Test Error!\n");
    }
    r_printf((0 == memcmp(au8Output, au8Plain,  u16OutByte)), "mh_rsa_public_EFC test\n");
}


void RSA_Test()
{
    RsaGenKey_Test();
    RsaComplete_Test();
    RsaPubFunc_Test();
    RsaPriFunc_Test();
    RsaCrtFunc_Test();
}
